UPDATE plt_file_artifact
SET lifecycle_status_code = 'ACTIVE', version = version + 1,
    update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.artifactId}
  AND lifecycle_status_code = 'DRAFT'
  AND version = #{query.expectedVersion}
  AND deleted = b'0'
